import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Gotchas & quirks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/gotchas.md","filePath":"guide/gotchas.md"}'),c={name:"guide/gotchas.md"};function i(r,e,d,n,l,p){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="gotchas-quirks" tabindex="-1">Gotchas &amp; quirks <a class="header-anchor" href="#gotchas-quirks" aria-label="Permalink to &quot;Gotchas &amp; quirks&quot;">​</a></h1><p>The sharp edges found while reading this build. Some are bugs, some are just surprising.</p><div class="danger custom-block"><p class="custom-block-title">Client <code>Side</code> reports <code>Server</code></p><p><code>CitizenFX.FiveM.Client.Core.Side</code> returns <code>Side.Server</code> — identical to the server side — which looks like a copy/paste bug in this decompiled build. <strong>Don&#39;t</strong> branch client-vs-server logic on <code>SharedAPI.Side</code> here. Split by assembly / by which side&#39;s script you&#39;re writing instead.</p></div><div class="warning custom-block"><p class="custom-block-title">Version lock-step</p><p><code>BaseEntrypoint.GetParameterAs</code> throws <em>&quot;Failed to find initialization parameter … Make sure your NuGet version matches server version&quot;</em> when an expected init key is missing. Compile against the exact runtime version your server ships, and never bundle your own copies of the <code>CitizenFX.*</code> / <code>MessagePack</code> assemblies (<code>&lt;Private&gt;false&lt;/Private&gt;</code>).</p></div><div class="warning custom-block"><p class="custom-block-title"><code>Core</code> APIs are internal (FIVEM001)</p><p>Members reached via <code>API.GetCore()</code> / <code>SharedAPI.GetCore()</code> carry <code>[Obsolete(... DiagnosticId = &quot;FIVEM001&quot;)]</code> — <em>&quot;intended only for internal usage and might be modified or removed without warning.&quot;</em> Stick to the static <code>API</code> / <code>SharedAPI</code> facades; treat anything on <code>Core</code> as unstable.</p></div><div class="warning custom-block"><p class="custom-block-title">Main-thread discipline</p><p>Emitting events and calling natives off the main thread throws <em>&quot;This function has to be called from the main thread only.&quot;</em> Background work must marshal back with <code>RunOnMainThread</code> / <code>await JumpToMainThread()</code> before touching the game. See <a href="./threading.html">Threading</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Client&#39;s <code>Native</code> lives in the <code>...Server</code> namespace</p><p>On the client, the <code>Native</code> class is compiled under <code>CitizenFX.FiveM.Server</code> (the file is at <code>Client/FiveM/Server/Native.cs</code>). Client code writes <code>using CitizenFX.FiveM.Server;</code> to call natives. Expected, not a bug.</p></div><div class="danger custom-block"><p class="custom-block-title">Networked events silently ignore <code>[OnEvent]</code></p><p>Only handlers with <code>AllowNetwork</code> (i.e. <code>[OnNetEvent]</code>) receive events whose source is <code>net:*</code>. A plain <code>[OnEvent]</code> on a networked event won&#39;t fire and won&#39;t warn. See <a href="./events.html">Events</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">Composite-format logging, not interpolation</p><p>The <code>Log.X(format, args)</code> overloads use <code>string.Format</code> with <code>{0}</code>-style placeholders. <code>API.Log.Info(&quot;x = {0}&quot;, x)</code> is correct; passing an already-interpolated string with a stray <code>{</code> can throw a format exception. Use the single-string overload for interpolated messages.</p></div><div class="info custom-block"><p class="custom-block-title">Unhandled exceptions can be fatal</p><p>A background exception that escapes to <code>AppDomain.UnhandledException</code> is routed to the host&#39;s <code>CriticalFailure</code>. Handler invocations are already wrapped by the managers; your own detached tasks/threads are not — guard them (or return <code>Task</code> so the wrapper logs faults).</p></div><div class="info custom-block"><p class="custom-block-title">Scripts need a public parameterless ctor</p><p>Discovery uses <code>Activator.CreateInstance(type)</code>. A class with only a parameterized constructor won&#39;t instantiate and will silently not load. Keep an implicit or explicit parameterless constructor.</p></div><div class="warning custom-block"><p class="custom-block-title">Command argument errors are swallowed to the log</p><p>If a caller passes an unparseable value, the command handler logs an error and does nothing — the player sees no feedback. Prefer nullable/defaulted parameters, or take <code>[FromRawCommand] string</code> and validate yourself. See <a href="./commands.html">Commands</a>.</p></div><hr><p>That&#39;s the tour. If a name or behaviour here doesn&#39;t match your server&#39;s assemblies, trust the assemblies — this reference tracks one decompiled build (<code>net10test</code>, v1.0.0.0) and the runtime is young.</p>',14)])])}const m=o(c,[["render",i]]);export{u as __pageData,m as default};
